export const vClickOutside = {
  beforeMount(el, binding) {
    el._cb = binding.value
    el._outside = (e) => {
      if (!el.contains(e.target)) el._cb(e)
    }
    // skip the click that opened the menu
    requestAnimationFrame(() => document.addEventListener('click', el._outside))
  },
  updated(el, binding) {
    el._cb = binding.value // do not add a second listener
  },
  unmounted(el) {
    document.removeEventListener('click', el._outside)
  },
  getSSRProps() {
    return { 'data-click-outside': '' } // first-paint attr only
  },
}

