  },
  updated(el, binding) {
    el._cb = binding.value // đừng thêm listener thứ hai
  },
  unmounted(el) {
    document.removeEventListener('click', el._outside)
  },
  getSSRProps() {
    return { 'data-click-outside': '' } // chỉ attr first paint
  },
}

