export const HttpKey: InjectionKey<HttpClient> = Symbol('http')

export function createHttpPlugin(options: { baseURL: string }) {
  return {
    install(app: App) {
      // client per-app: SSR là một app mỗi request
      const client = createHttp(options.baseURL)
      app.provide(HttpKey, client)
      const prev = app.config.errorHandler
      app.config.errorHandler = (err, instance, info) => {
        client.report(err)
        if (prev) prev(err, instance, info) // compose, đừng thay
      }
    },
  }
}

