import { provide, inject, readonly, ref, type InjectionKey, type Ref } from 'vue'

export const FormKey: InjectionKey<{
  disabled: Readonly<Ref<boolean>>
  setDisabled: (v: boolean) => void
}> = Symbol('form')

export function provideForm() {
  const disabled = ref(false)
  provide(FormKey, {
    disabled: readonly(disabled),
    setDisabled: (v) => { disabled.value = v },
  })
}

export function useForm() {
  // factory default — do not share one object across instances
  return inject(FormKey, () => ({
    disabled: readonly(ref(false)),
    setDisabled: () => {},
  }), true)
}

