router.beforeEach(async (to) => {
  const auth = useAuthStore()
  if (!auth.ready) await auth.hydrate() // once per session, not per navigation
  if (to.meta.requiresAuth && !auth.isLoggedIn) {
    return { path: '/login', query: { redirect: to.fullPath } }
  }
  const roles = to.matched
    .flatMap((r) => (r.meta.roles as string[] | undefined) ?? [])
  if (roles.length && !roles.some((r) => auth.roles.includes(r))) {
    return { path: '/403' }
  }
  // Vue Router 4: return a location or nothing — do not call next()
})

